package io.forgeloop.control.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import io.forgeloop.control.domain.*;import java.util.*;import org.junit.jupiter.api.Test;
class RunAnalyticsServiceTest {
 @Test void aggregatesModelsHarnessesTokensAndKnownCost(){FeatureRunService runs=mock(FeatureRunService.class);FeatureRun run=mock(FeatureRun.class);DeliveryTask task=mock(DeliveryTask.class);ProviderAttempt attempt=mock(ProviderAttempt.class);when(runs.list()).thenReturn(List.of(run));when(run.getTasks()).thenReturn(List.of(task));when(run.getHarnessProfile()).thenReturn("JAVA_WEB");when(run.getState()).thenReturn(RunState.COMPLETE);when(task.getProviderAttempts()).thenReturn(List.of(attempt));when(attempt.getProvider()).thenReturn("anthropic");when(attempt.getModel()).thenReturn("claude");when(attempt.getOutcome()).thenReturn("SUCCEEDED");when(attempt.getInputTokens()).thenReturn(10L);when(attempt.getOutputTokens()).thenReturn(5L);when(attempt.isCostKnown()).thenReturn(true);when(attempt.getEstimatedCostMicros()).thenReturn(25L);var result=new RunAnalyticsService(runs).snapshot();assertEquals(1,result.totalRuns());assertEquals(1,result.deliveredRuns());assertEquals(15,result.inputTokens()+result.outputTokens());assertEquals(25,result.knownCostMicros());assertEquals("anthropic/claude",result.modelComparisons().getFirst().name());assertEquals("JAVA_WEB",result.harnessComparisons().getFirst().name());}
}
